          <span class="step-number">5</span>
        </div>
      </div>
    </div>
    <!-- Content Container -->
    <div class="process-content-container row align-items-center mt-5">
      <!-- Left Side: Large Active Step Name -->
      <div class="col-lg-5">
        <h3 class="process-step-heading text-white" id="active-step-title">Discussion and Research</h3>
      </div>
      <!-- Right Side: Dark Card Content -->
      <div class="col-lg-7 mt-4 mt-lg-0">
        <div class="process-details-card">
          <div id="process-step-content-area">
            <!-- Content will be swapped via JS -->
          </div>
        </div>
      </div>
    </div>
  </div>
</section>
<script>
  document.addEventListener('DOMContentLoaded', function() {
    const stepsData = {
      1: {
        title: "Discussion and Research",
        items: [{
          desc: "As the most trusted Pinterest ads agency, we believe in understanding the unique brand proposition and specific goals of your business first through full-fledged discussion and collaboration."
        }]
      },
      2: {
        title: "Development",
        items: [{
          desc: "After we are done with the initial discussions, we will analyze your past marketing campaign data to build a results-driven strategy. As the #1 Pinterest Marketing Company in Dubai, our in-house creative will do their best to come up with highly engaging Pinterest ad content."
        }]
      },
      3: {
        title: "Monitoring Your Pinterest Ad Campaign",
        items: [{
          desc: "Standing up to our reputation of being the most reliable Pinterest Marketing Agency in Dubai, we will continuously monitor your ad campaign's performance to understand which aspects are yielding optimal results."
        }]
      },
      4: {
        title: "Refining Your Pinterest Campaign",
        items: [{
          desc: "Once we identify what's working for your brand and what isn't, we will refine it accordingly."
        }]
      },
      5: {
        title: "Reporting Data",
        items: [{
          desc: "When you hire Brandstory for Pinterest Marketing Services in Dubai, you will realize that your marketing cost is well-spent. We will provide you with real-time tracking data to help you understand how our campaigns are bringing results for your brand."
        }]
      }
    };
    const stepNodes = document.querySelectorAll('.process-step-node');
    const activeLine = document.querySelector('.process-timeline-line-active');
    const titleElement = document.getElementById('active-step-title');
    const contentArea = document.getElementById('process-step-content-area');

    function updateStep(stepIndex) {
      // Update nodes states
      stepNodes.forEach(node => {
        const nodeStep = parseInt(node.getAttribute('data-step'));
        if (nodeStep <= stepIndex) {
          node.classList.add('active');
        } else {
          node.classList.remove('active');
        }
      });
      // Update active line progress
      if (activeLine && stepNodes.length > 0) {
        const firstNode = stepNodes[0];
        const activeNode = stepNodes[stepIndex - 1];
        if (firstNode && activeNode) {
          const firstCenter = firstNode.offsetLeft + (firstNode.offsetWidth / 2);
          const activeCenter = activeNode.offsetLeft + (activeNode.offsetWidth / 2);
          activeLine.style.left = firstCenter + 'px';
          activeLine.style.width = (activeCenter - firstCenter) + 'px';
        }
      }
      // Update content
      const stepData = stepsData[stepIndex];
      if (stepData) {
        if (titleElement) {
          titleElement.textContent = stepData.title;
        }
        let htmlContent = '';
        stepData.items.forEach(item => {
          htmlContent += `
            <div class="process-card-item">
              ${item.title ? `<h4 class="text-white font-weight-bold mb-2">${item.title}</h4>` : ''}
              <p class="process-card-desc mb-0">${item.desc}</p>
            </div>
          `;
        });
        if (contentArea) {
          contentArea.innerHTML = htmlContent;
        }
      }
    }
    // Add click listeners
    stepNodes.forEach(node => {
      node.addEventListener('click', function() {
        const stepIndex = parseInt(this.getAttribute('data-step'));
        updateStep(stepIndex);
      });
    });
    // Initialize first step
    updateStep(1);
  });
</script>

